import nbformat as n
from pathlib import Path
nb=n.v4.new_notebook()
cells=[('m','# VideoLens — Phân tích và tóm tắt video\nPython 3.13. Chạy lần lượt các ô. Đổi VIDEO thành đường dẫn video của bạn. Video tổng hợp chỉ dùng kiểm thử kỹ thuật, không chứng minh chất lượng trên TVSum/SumMe.'),('c','from pathlib import Path\nimport sys\nROOT = Path.cwd()\nif not (ROOT / "core.py").exists(): ROOT = ROOT.parent\nsys.path.insert(0, str(ROOT))\nfrom core import analyze, select, export_video, summary_f1, boundary_f1\nimport pandas as pd\nimport plotly.express as px\nfrom IPython.display import Video, display\nVIDEO = ROOT / "runs" / "synthetic.mp4"\nOUT = ROOT / "runs" / "notebook"'),('m','## 1. Đặc trưng và chuyển cảnh\nLược đồ HSV 16×8; khoảng cách Bhattacharyya; sai khác mức xám; Farneback flow; Haar face; phương sai Laplacian. Ngưỡng cảnh = max(0.12, median + k × 1.4826 × MAD). Lấy mẫu làm giảm chi phí nhưng có thể bỏ sót cảnh ngắn.'),('c','df, meta = analyze(VIDEO, OUT, sample_fps=2)\ndisplay(pd.DataFrame([meta]))\ndisplay(df.head())'),('c','px.line(df, x="time", y=["motion_norm", "color_norm", "faces_norm"]).show()'),('m','## 2. Chọn đoạn\nKMeans trên histogram, seed 42. Chấm điểm tổng có trọng số; chọn tham lam cộng thưởng cụm chưa xuất hiện dưới ngân sách thời lượng. Không bảo đảm tối ưu knapsack; giữ thứ tự thời gian. Cảnh dài được chia thành đoạn tối đa 4 giây.'),('c','segments, scores = select(df, meta, ratio=.25)\ndisplay(pd.DataFrame(segments))\nresult = export_video(VIDEO, segments, OUT)\ndisplay(Video(str(result), embed=True))'),('m','## 3. Đánh giá và ablation\nThay LABELS bằng nhãn người thật đúng video. F1 ranh giới ghép một-một trong sai số 0.5 giây. F-score tóm tắt đo giao của mặt nạ thời gian, phân giải 0.1 giây. Báo cáo cả mean và max, nêu rõ giao thức khi so sánh công trình khác.'),('c','import json\nLABELS = ROOT / "examples" / "labels.json"\ngt = json.loads(LABELS.read_text())\nprint("Boundary F1:", boundary_f1(meta["cuts"], gt["boundaries"]))\nrows=[]\nfor mode, diversity in [("balanced",True),("balanced",False),("motion",False),("no_motion",True)]:\n    selected,_ = select(df,meta,.25,mode,diversity)\n    metric = summary_f1(selected,gt["summaries"],meta["duration"])\n    rows.append({"method":mode,"diversity":diversity,**metric})\ndisplay(pd.DataFrame(rows))'),('m','## 4. Thảo luận\nThử tỷ lệ 10%, 15%, 25%; tốc độ lấy mẫu 1/2/5 fps; đo thời gian xử lý. Dùng cùng ngân sách cho mọi phương pháp. Chọn trọng số trên tập validation, giữ test độc lập theo video. Đánh giá riêng thể thao và bài giảng. Không suy diễn chất lượng ngữ nghĩa từ độ mạnh chuyển động.')]
nb.cells=[n.v4.new_markdown_cell(s) if t=='m' else n.v4.new_code_cell(s) for t,s in cells]
nb.metadata={'kernelspec':{'display_name':'Python 3.13','language':'python','name':'python3'}}
n.write(nb,'VideoLens.ipynb')
